-- Mod-authored era splash descriptions, de_DE overlay.
-- Baseline in CivVAccess_EraDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_MISSING"] = "Keine Beschreibung für diese Epoche."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_CLASSICAL"] =
    "Ein großer Säulentempel thront auf einem terrassierten Hügel; kleinere Kolonnaden stufen sich rechts davon den Hang hinab. Gärten erklimmen den Abhang darunter, wo schmale Treppen an einem blassen Felsvorsprung vorbeiführen, der von Zypressen und blühenden Sträuchern überwuchert ist. Der gesamte Marmor erstrahlt warm golden in der Sonne."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_MEDIEVAL"] =
    "Goldene Weizenfelder breiten sich unter einer ummauerten Stadt aus blassen Türmen auf einem Hügel aus. Rote Banner hängen von ihren Zinnen; das größte trägt einen schwarzen Vogel mit ausgebreiteten Schwingen. Es ist Erntezeit: gebeugte Bauern sammeln das geschnittene Getreide, andere tragen hohe Garben auf dem Rücken, und Arbeiter in der Mitte beladen einen Wagen, der von zwei dunklen Ochsen gezogen wird. Bäume neigen sich an den oberen Ecken unter einem sanft dunstigen Himmel herein."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_RENAISSANCE"] =
    "Hoch über den Dächern Florenz' steht Michelangelo auf einer hölzernen Leiter und meißelt den kolossalen weißen Marmor-David. Kopf und Schultern der Statue allein füllen die linke Bildhälfte; der Bildhauer reicht kaum bis an ihre Schulter. Darunter erstrecken sich rote Ziegeldächer bis hin zur großen Kuppel des Florentiner Doms und einem schlanken Glockenturm. Dahinter bricht goldenes Licht durch den sturmfinsteren Himmel."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_INDUSTRIAL"] =
    "Ein rot-weißes Schaufelraddampfschiff überquert im Vordergrund den Hafen von New York und zieht Rauch aus zwei schwarzen Schornsteinen. Passagiere reihen sich auf seinen Doppeldecks. Dahinter erhebt sich die Freiheitsstatue grün vor einem dunstigen bernsteinfarbenen Himmel; weitere Schiffe dampfen jenseits davon über das Wasser. Rauch und Dunst tauchen die ganze Szene in warmes Sepia und Gold."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_MODERN"] =
    "Der Blick reicht vom Dach eines Hochhauses über eine Stadt voller Wolkenkratzer. Beleuchtete Türme erstrecken sich Block für Block in goldenen Dunst. Weit unten schlängeln sich Hochstraßen durch ein weitläufiges Kreuz, auf dem Autos und Lastwagen die Kurven entlangströmen. Das ganze Gemälde ist eine einzige Farbe, Gold und Sepia wie auf einem getönten Foto."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_POSTMODERN"] =
    "Eine tief stehende Sonne brennt am Ende einer Innenstadtstraße der Mitte des zwanzigsten Jahrhunderts und taucht sie in goldenes Licht. Männer in Anzügen und Filzhüten gehen auf dem rechten Gehsteig mit dem Rücken zum Betrachter, vorbei an Markisen und einer großen Leuchtschrifttafel. Abgerundete dunkle Limousinen parken am Bordstein oder rollen vorüber. Weiter vorn lösen sich die Gebäude im Gegenlicht auf."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_FUTURE"] =
    "Eine futuristische Stadt glänzt entlang einer goldenen Küste, ihre schlanken Türme erstrecken sich das Ufer hinauf in den Dunst. Links schwenkt ein schnittig-rotes-und-weißes Düsenflugzeug über das Wasser; dahinter überspannt eine Hängebrücke die Bucht. Im rechten Vordergrund ist ein kuppelgekrönter Komplex aus Chrom und Glas in die Meeresküste selbst eingebaut. Grünpflanzen säumen seine Absätze; eine einzelne Gestalt steht auf einem Laufsteg."
